/*
 * A048689  Number of classes generated by function A001222 when applied to
 *          binomial coefficients.
 * https://oeis.org/A048689
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = number of distinct values of A001222(C(n,k)), i.e. the
 *            number of distinct big‑omega values of the binomial coefficients
 *            C(n,k), 0 ≤ k ≤ n
 * Range:     u8 n <= 50, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stdlib.h>
#include <stddef.h>

/* ----------  small sieve cache  ---------- */
static struct {
    size_t sz;       /* number of elements in spf (max n + 1) */
    seq_t *spf;      /* smallest prime factor of each integer */
} _spf_cache = {0, NULL};

/* Ensure that _spf_cache.spf contains the smallest prime factor for
   all integers 2 … n.  The array grows only when requested with a
   larger n. */
static void _ensure_spf(size_t n)
{
    if (n < _spf_cache.sz) return;                 /* already ready */

    size_t new_sz = n + 1;
    seq_t *new_spf = (seq_t *)calloc(new_sz, sizeof(seq_t));
    if (!new_spf) return;                          /* allocation failed */

    for (size_t i = 2; i < new_sz; ++i) {
        if (new_spf[i] == 0) {                     /* prime i */
            new_spf[i] = (seq_t)i;
            if (i * i < new_sz) {
                for (size_t j = i * i; j < new_sz; j += i)
                    if (new_spf[j] == 0) new_spf[j] = (seq_t)i;
            }
        }
    }

    free(_spf_cache.spf);
    _spf_cache.spf = new_spf;
    _spf_cache.sz   = new_sz;
}

/* ----------  main sequence function  ---------- */
seq_t a(idx_t n)
{
    if (n == 0) return 0;                        /* undefined below offset */

    /* prepare sieve up to n */
    _ensure_spf((size_t)n);

    /* maximum possible big‑omega of any binomial coefficient C(n,k)
       is bounded by Omega(n!), roughly n log log n.
       For n ≤ 10000 this is far below 5·n, so we allocate a
       visited array of size 5·n+1. */
    size_t visited_limit = 5 * (size_t)n + 1;

    bool *visited = (bool *)calloc(visited_limit, sizeof(bool));
    if (!visited) return 0;                      /* allocation failed */

    /* exponent array for every prime up to n (primes < n → exponent 0) */
    seq_t *exp = (seq_t *)calloc((size_t)n + 1, sizeof(seq_t));
    if (!exp) {
        free(visited);
        return 0;
    }

    seq_t omega_total = 0;  /* big‑omega of current C(n,k) */

    /* C(n,0) = 1 has big‑omega 0 */
    visited[0] = true;
    size_t seen = 1;         /* number of distinct omega values seen */

    for (idx_t k = 1; k <= n; ++k) {
        /* factor numerator (n - k + 1) */
        size_t x = (size_t)(n - k + 1);
        while (x > 1) {
            size_t p = (size_t)_spf_cache.spf[x];
            seq_t  cnt = 0;
            while (x % p == 0) { x /= p; ++cnt; }
            exp[p] += cnt;
            omega_total += cnt;
        }

        /* factor denominator k */
        x = (size_t)k;
        while (x > 1) {
            size_t p = (size_t)_spf_cache.spf[x];
            seq_t  cnt = 0;
            while (x % p == 0) { x /= p; ++cnt; }
            exp[p] -= cnt;
            omega_total -= cnt;
        }

        /* record omega_total */
        if (omega_total < (seq_t)visited_limit) {
            if (!visited[(size_t)omega_total]) {
                visited[(size_t)omega_total] = true;
                ++seen;
            }
        }
        /* omega_total will never exceed visited_limit for n ≤ 10000 */
    }

    free(exp);
    free(visited);
    return (seq_t)seen;
}
